CREATE TABLE administration_tenants(id UUID PRIMARY KEY,code VARCHAR(64) NOT NULL UNIQUE,name VARCHAR(128) NOT NULL,status VARCHAR(32) NOT NULL,plan VARCHAR(64) NOT NULL,configuration JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE administration_roles(id UUID PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES administration_tenants(id),name VARCHAR(128) NOT NULL,description VARCHAR(512),status VARCHAR(32) NOT NULL,permissions JSONB NOT NULL,CONSTRAINT uq_role_tenant_name UNIQUE(tenant_id,name));
CREATE TABLE administration_permissions(id UUID PRIMARY KEY,tenant_id UUID,code VARCHAR(128) NOT NULL,description VARCHAR(512),scope VARCHAR(32) NOT NULL,status VARCHAR(32) NOT NULL,CONSTRAINT uq_permission_scope_code UNIQUE(tenant_id,code));
CREATE TABLE administration_configurations(id UUID PRIMARY KEY,tenant_id UUID,key_name VARCHAR(128) NOT NULL,value_json JSONB NOT NULL,module VARCHAR(128) NOT NULL,version INT NOT NULL,updated_at TIMESTAMPTZ NOT NULL,CONSTRAINT uq_config_scope_key UNIQUE(tenant_id,module,key_name));
CREATE TABLE administration_feature_flags(id UUID PRIMARY KEY,tenant_id UUID,key_name VARCHAR(128) NOT NULL,enabled BOOLEAN NOT NULL,version INT NOT NULL,activate_at TIMESTAMPTZ,updated_at TIMESTAMPTZ NOT NULL,CONSTRAINT uq_flag_scope_key UNIQUE(tenant_id,key_name));
CREATE TABLE administration_audit(id UUID PRIMARY KEY,tenant_id UUID,actor_id UUID,action VARCHAR(64) NOT NULL,resource_type VARCHAR(64) NOT NULL,resource_id UUID,result VARCHAR(32) NOT NULL,correlation_id UUID,created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX idx_admin_roles_tenant_status ON administration_roles(tenant_id,status);CREATE INDEX idx_admin_audit_tenant_time ON administration_audit(tenant_id,created_at);CREATE INDEX idx_admin_flags_tenant ON administration_feature_flags(tenant_id);
